'use strict';
function backTop(t,extra){return `<div class="top">${U.page?`<button class="ib" data-a="back" aria-label="Voltar">${IC.l}</button>`:''}<h1 class="grow">${esc(t)}</h1>${extra||''}</div>`}
const inMonth=(d,ym)=>d&&d.slice(0,7)===ym;

/* ---------- FINANÇAS ---------- */
function finCalc(area){
  const ym=D.today().slice(0,7),f=x=>area==='tudo'||x.area===area;
  const bills=S.bills.filter(b=>f(b)&&inMonth(b.due,ym));
  const billsT=bills.reduce((a,b)=>a+b.value,0),billsOpen=S.bills.filter(b=>f(b)&&b.status!=='pago').reduce((a,b)=>a+b.value,0);
  const debtM=S.debts.filter(f).reduce((a,d)=>a+(d.balance>0?d.monthly:0),0);
  const wishM=area==='dune'?0:S.wishes.filter(w=>w.goal&&w.goal.on&&!w.goal.paused).reduce((a,w)=>a+w.goal.monthly,0);
  const wishDone=area==='dune'?0:S.wishes.reduce((a,w)=>a+((w.goal&&w.goal.contribs)||[]).filter(c=>inMonth(c.date,ym)).reduce((x,c)=>x+c.value,0),0);
  const extra=area==='pessoal'?0:S.fin.reserveDebt;
  const inc=S.fin.inc.filter(i=>f(i)&&inMonth(i.date,ym));
  const rec=inc.filter(i=>i.status==='recebido').reduce((a,i)=>a+i.value,0),prev=inc.filter(i=>i.status==='previsto').reduce((a,i)=>a+i.value,0);
  const spent=S.fin.spend.filter(s=>f(s)&&inMonth(s.date,ym)).reduce((a,s)=>a+s.value,0);
  const need=billsT+debtM+extra+wishM;
  return {ym,bills,billsT,billsOpen,debtM,wishM,wishDone,extra,rec,prev,spent,need,falta:Math.max(0,need-rec),sobra:rec+prev-billsT-debtM-extra-spent};
}
SCREENS.fin=()=>{
  const ar=U.finArea,c=finCalc(ar),T=D.today(),fa=x=>ar==='tudo'||x.area===ar;
  let h=`<div class="top"><h1 class="grow">Finanças</h1><button class="btn sm dune" data-a="sheet" data-v="gasto">+ Lançar gasto</button></div>
  <div class="seg">${[['tudo','Tudo'],['pessoal','Pessoal'],['dune','DUNE'],['extra','Extras']].map(([k,l])=>`<button class="${ar===k?'on':''}" data-a="setU" data-k="finArea" data-v="${k}">${l}</button>`).join('')}</div>
`;
  if(ar==='extra'){const ex=S.fin.inc.filter(i=>i.area==='extra').sort((a,b)=>a.date<b.date?1:-1);
    return h+extrasCard()+`<div class="sec"><h2>Receitas extras</h2></div><div class="card">${ex.map(i=>`<div class="li"><button class="t" style="text-align:left" data-a="sheet" data-v="income" data-id="${i.id}"><b>${esc(i.desc)}</b><small class="mut">${D.short(i.date)} · ${i.status}</small></button><b class="num" style="color:${i.status==='recebido'?'var(--ok)':'var(--ink2)'}">${i.value?brl(i.value):'<span class="pill demo">a confirmar</span>'}</b><button class="btn sm ${i.status==='recebido'?'sec2':'pes'}" data-a="incTog" data-id="${i.id}">${i.status==='recebido'?'Desfazer':'Recebi'}</button></div>`).join('')}</div>
    <div class="sec"><h2>Projetos extras</h2><button class="link" data-a="projExtra">Projetos</button></div><div class="card">${S.projects.filter(p=>p.area==='extra').map(p=>`<div class="li"><span class="t"><b>${esc(p.name)}</b><small class="mut">${esc(p.status)} · até ${D.short(p.due)}</small></span></div>`).join('')}</div>`}
  h+=`<div class="card" style="margin-top:12px"><small class="mut">Para cobrir ${esc(D.mesNome(T))}</small><div class="row" style="align-items:flex-end"><div class="grow"><div class="big num">${brl(c.need)}</div><small class="mut">necessário no mês</small></div><div style="text-align:right"><b class="num" style="color:var(--ok)">${brl(c.rec)}</b><br><small class="mut">já entrou</small></div></div>
   <div class="bar" style="margin:10px 0"><i style="width:${Math.min(100,c.need?c.rec/c.need*100:100)}%"></i></div>
   <div class="row"><span class="grow">Falta receber</span><b class="num" style="color:${c.falta?'var(--sos)':'var(--ok)'}">${brl(c.falta)}</b></div>
   <details style="margin-top:8px"><summary class="link" style="padding:6px 0">Composição da conta</summary>
    <div class="kv"><span>Contas do mês</span><b class="num">${brl(c.billsT)}</b></div><div class="kv"><span>Pagamentos de dívidas previstos</span><b class="num">${brl(c.debtM)}</b></div>${ar!=='pessoal'?`<div class="kv"><span>Reserva para adiantar dívidas</span><b class="num">${brl(c.extra)}</b></div>`:''}${ar!=='dune'?`<div class="kv"><span>Aportes planejados em desejos</span><b class="num">${brl(c.wishM)}</b></div>`:''}
   </details></div>
  <div class="grid2" style="margin-top:10px"><div class="card"><small class="mut">Faturamento previsto</small><div class="num" style="font-size:19px;font-weight:600">${brl(c.prev)}</div><small class="mut tiny">ainda não entrou</small></div><div class="card"><small class="mut">Dinheiro recebido</small><div class="num" style="font-size:19px;font-weight:600;color:var(--ok)">${brl(c.rec)}</div><small class="mut tiny">no caixa</small></div></div>
  <div class="grid2" style="margin-top:10px"><div class="card"><small class="mut">Gastos do mês</small><div class="num" style="font-size:19px;font-weight:600">${brl(c.spent)}</div></div><div class="card"><small class="mut">Em aberto (contas)</small><div class="num" style="font-size:19px;font-weight:600">${brl(c.billsOpen)}</div></div></div>`;
  if(ar==='dune'){const ex=S.fin.inc.filter(i=>i.area==='extra'&&i.status==='recebido'&&inMonth(i.date,c.ym)).reduce((a,i)=>a+i.value,0);if(ex)h+=`<p class="note">Extras deste mês: <b>${brl(ex)}</b>. Caem no CNPJ da DUNE, mas ficam separados em “Extras”.</p>`}
  // vencimentos
  const due=S.bills.filter(b=>fa(b)&&b.status!=='pago'&&D.diff(T,b.due)<=7).sort((a,b)=>a.due<b.due?-1:1);
  h+=`<div class="sec"><h2>Vence hoje e em 7 dias</h2><button class="link" data-a="sheet" data-v="bill">+ Conta</button></div><div class="card">${due.map(billRow).join('')||'<p class="empty">Nada vencendo.</p>'}</div>`;
  // simulador
  if(ar!=='pessoal'){const meta=c.billsT+c.debtM+S.fin.reserveDebt+c.wishM;
  h+=`<div class="sec"><h2>Meta de faturamento</h2></div><div class="card"><div class="row"><span class="grow">Reservar para adiantar dívidas</span><b class="num" id="rdv">${brl(S.fin.reserveDebt)}</b></div><input type="range" min="0" max="3000" step="50" value="${S.fin.reserveDebt}" data-in="reserve" aria-label="Reserva para adiantar dívidas">
   <div class="kv"><span>Meta mensal simulada</span><b class="num" id="rmeta">${brl(meta)}</b></div><div class="kv"><span>Recebido + previsto</span><b class="num">${brl(c.rec+c.prev)}</b></div><div class="kv"><span>Diferença</span><b class="num" id="rdif" style="color:${c.rec+c.prev-meta<0?'var(--red)':'var(--ok)'}">${brl(c.rec+c.prev-meta)}</b></div>
   <p class="tiny mut" style="margin:6px 0 0">Com ${brl(S.fin.reserveDebt)}/mês extras, as dívidas terminam em <b id="rdq">${debtEnd(S.fin.reserveDebt)}</b>.</p></div>`;}
  // sobra
  h+=`<div class="card"><div class="row"><span class="grow">Sobra depois de contas, dívidas e reservas</span><b class="num" style="color:${c.sobra<0?'var(--red)':'var(--ok)'}">${brl(c.sobra)}</b></div><small class="mut tiny">recebido + previsto − contas do mês − dívidas − reserva − gastos lançados</small></div>`;
  // reservas desejos
  if(ar!=='dune')h+=`<div class="sec"><h2>Reservas para desejos</h2><button class="link" data-a="go" data-v="desejos">Desejos</button></div><div class="card"><div class="kv"><span>Planejado reservar este mês</span><b class="num">${brl(c.wishM)}</b></div><div class="kv"><span>Efetivamente reservado</span><b class="num" style="color:var(--ok)">${brl(c.wishDone)}</b></div>${S.wishes.filter(w=>w.goal&&w.goal.on).map(w=>`<button class="li" data-a="openWish" data-id="${w.id}"><span class="t"><b>${esc(w.name)}</b><small class="mut">${brl(w.goal.saved)} guardados · ${w.goal.paused?'pausado':brl(w.goal.monthly)+'/mês'}</small></span>${IC.r}</button>`).join('')}<p class="tiny mut" style="margin:6px 0 0">Aporte é dinheiro reservado: não entra como gasto.</p></div>`;
  // dívidas
  const debts=S.debts.filter(fa);
  if(debts.length)h+=`<div class="sec"><h2>Dívidas</h2></div><div class="card">${debts.map(d=>`<button class="li" data-a="sheet" data-v="debt" data-id="${d.id}"><span class="t"><b>${esc(d.name)}</b><small class="mut">${areaPill(d.area)} parcela ${brl(d.monthly||d.mPlan||0)} · ${d.pays.length} ${d.pays.length===1?'pagamento':'pagamentos'}</small></span><b class="num">${brl(d.balance)}</b></button>`).join('')}</div>`;
  // receitas
  const inc=S.fin.inc.filter(i=>fa(i)&&(inMonth(i.date,c.ym)||(ar==='extra'&&i.status==='previsto'))).sort((a,b)=>a.date<b.date?-1:1);
  h+=`<div class="sec"><h2>Receitas do mês</h2><button class="link" data-a="sheet" data-v="income">+ Receita</button></div><div class="card">${inc.map(i=>`<div class="li"><button class="t" style="text-align:left" data-a="sheet" data-v="income" data-id="${i.id}"><b>${esc(i.desc)}</b><small class="mut">${areaPill(i.area)} ${D.short(i.date)} · ${i.status}</small></button><b class="num" style="color:${i.status==='recebido'?'var(--ok)':'var(--ink2)'}">${i.value?brl(i.value):'<span class="pill demo">a confirmar</span>'}</b><button class="btn sm ${i.status==='recebido'?'sec2':'pes'}" data-a="incTog" data-id="${i.id}">${i.status==='recebido'?'Desfazer':'Recebi'}</button></div>`).join('')||'<p class="empty">Sem receitas lançadas.</p>'}</div>`;
  // gastos
  const sp=S.fin.spend.filter(fa).sort((a,b)=>a.date<b.date?1:-1).slice(0,12);
  h+=`<div class="sec"><h2>Histórico de gastos</h2></div><div class="card">${sp.map(s=>`<button class="li" style="width:100%;text-align:left" id="sp-${s.id}" data-a="sheet" data-v="spendView" data-id="${s.id}"><span class="t"><b>${esc(s.desc)}</b><small class="mut">${areaPill(s.area)} ${D.short(s.date)}${s.cat?' · '+esc(s.cat):''}${s.pay?' · '+esc(s.pay):''}</small><small class="row wrap" style="gap:4px;margin-top:3px">${syncPills(s)}</small></span><b class="num">${brl(s.value)}</b></button>`).join('')||'<p class="empty">Nenhum gasto.</p>'}</div>
  <div class="card"><div class="row"><b class="grow">Todas as contas</b></div>${S.bills.filter(fa).sort((a,b)=>a.due<b.due?-1:1).map(billRow).join('')}</div>
  <p class="note demo">${demo('sincronização')} Os lançamentos e totais funcionam aqui com dados locais. Na publicação, cada gasto é gravado primeiro no banco do MMV e depois enviado ao Claude e aos sistemas financeiros conectados.</p>`;
  return h;
};
function debtEnd(extra){let tot=S.debts.reduce((a,d)=>a+d.balance,0),m=S.debts.reduce((a,d)=>a+d.monthly,0)+(+extra||0);if(!m)return '—';const n=Math.ceil(tot/m);const d=D.add(D.today(),n*30);return `${n} meses (${MES[+d.slice(5,7)-1]}/${d.slice(2,4)})`}
function syncPills(s){const y=s.sync||{};const p=(k,l)=>y[k]==='ok'?`<span class="pill ok">${l} ✓</span>`:y[k]==='falhou'?`<span class="pill bad">${l}: falhou</span><button class="link tiny" style="padding:0 4px" data-a="retry" data-id="${s.id}">Tentar novamente</button>`:`<span class="pill demo">${l} · demo</span>`;return p('mmv','MMV')+p('claude','Claude')+p('fin','Sist. financeiro')}
A.retry=(ds)=>{const s=S.fin.spend.find(x=>x.id===ds.id);s.sync.fin='demo';s.sync.retries=(s.sync.retries||0)+1;U.keepScroll=true;save();toast('Reenviado com o mesmo ID: sem duplicar')};
A.incTog=(ds)=>{const i=S.fin.inc.find(x=>x.id===ds.id);i.status=i.status==='recebido'?'previsto':'recebido';if(i.status==='recebido')i.recAt=D.today();U.keepScroll=true;save()};
A.reserve=(el)=>{S.fin.reserveDebt=+el.value;const c=finCalc(U.finArea),meta=c.billsT+c.debtM+S.fin.reserveDebt+c.wishM;$('#rdv').textContent=brl(S.fin.reserveDebt);$('#rmeta').textContent=brl(meta);const df=c.rec+c.prev-meta;$('#rdif').textContent=brl(df);$('#rdif').style.color=df<0?'var(--red)':'var(--ok)';$('#rdq').textContent=debtEnd(S.fin.reserveDebt);clearTimeout(A._rt);A._rt=setTimeout(()=>save({quiet:true}),500)};

/* gasto rápido */
function parseExpense(t){
  const n=norm(t),r={value:'',desc:'',area:'',date:D.today(),cat:''};
  const m=n.match(/r\$\s*(\d+(?:[.,]\d{1,2})?)/)||n.match(/(\d+(?:[.,]\d{1,2})?)\s*(?:reais|real|conto)/)||n.match(/(\d+(?:[.,]\d{1,2})?)/);if(m)r.value=num(m[1]);
  if(/\b(dune|agencia|empresa|trabalho)\b/.test(n))r.area='dune';else if(/\bpessoal\b/.test(n))r.area='pessoal';
  if(/\bontem\b/.test(n))r.date=D.add(D.today(),-1);else if(/\banteontem\b/.test(n))r.date=D.add(D.today(),-2);else{const d=parseDate(t);if(d&&d<=D.today())r.date=d}
  const dm=t.match(/(?:reais|real|r\$\s*[\d.,]+)\s+(?:de|com|no|na|em)\s+([^,.]+?)(?=\s+(?:hoje|ontem|anteontem|pessoal|dune|pela|pelo|para)\b|[,.]|$)/i)||t.match(/\b(?:de|com|no|na)\s+([a-zà-ú ]{3,30}?)(?=\s+(?:hoje|ontem|pessoal|dune)\b|[,.]|$)/i);
  if(dm)r.desc=dm[1].trim().replace(/^./,c=>c.toUpperCase());
  const cats=[[/gasolina|combust|uber|99|onibus|estacion|pedagio/,'Transporte'],[/mercado|ifood|almoco|jantar|lanche|padaria|restaurante|cafe/,'Alimentação'],[/canva|adobe|figma|software|assinatura|banco de imagens/,'Ferramentas'],[/farmacia|remedio|consulta/,'Saúde'],[/aluguel|luz|agua|internet/,'Moradia']];
  for(const [re,c] of cats)if(re.test(n)){r.cat=c;break}
  return r;
}
SHEETS.gasto=(a)=>{const p=a.pre||{date:D.today(),area:''};
  return {title:'Lançar gasto',body:`<div class="row" style="gap:8px;align-items:flex-end"><label class="fld grow" style="margin:0"><span>Diga ou digite</span><input id="tx-gasto" value="${esc(a.from||'')}" placeholder="Gastei 38 reais de gasolina hoje, pessoal"></label><button class="mic" data-a="mic" data-ctx="gasto" aria-label="Ditado">${IC.mic}</button></div>
  <div class="row" style="gap:8px;margin-top:8px"><button class="btn sm sec2" data-a="gParse">Preencher campos</button><button class="btn sm sec2" data-a="demoAudio" data-ctx="gasto">Exemplo falado</button></div>
  ${a.from?`<p class="note">Confira os campos preenchidos a partir de: “${esc(a.from)}”</p>`:''}
  <div class="grid2"><label class="fld"><span>Valor (R$)</span><input id="gv" inputmode="decimal" value="${p.value?String(p.value).replace('.',','):''}" placeholder="0,00"></label><label class="fld"><span>Data</span><input type="date" id="gd" value="${p.date}"></label></div>
  <label class="fld"><span>Descrição</span><input id="gdesc" value="${esc(p.desc||'')}"></label>
  <div class="fld"><span>Pessoal ou DUNE?</span><div class="seg" id="garea">${['pessoal','dune'].map(k=>`<button class="${p.area===k?'on':''}" data-a="gArea" data-v="${k}">${k==='dune'?'DUNE':'Pessoal'}</button>`).join('')}</div></div>
  <details style="margin-top:10px" ${p.cat?'open':''}><summary class="link" style="padding:8px 0">Detalhes opcionais</summary>
  <div class="grid2"><label class="fld"><span>Categoria</span><input id="gcat" value="${esc(p.cat||'')}" list="cats"><datalist id="cats">${['Transporte','Alimentação','Ferramentas','Saúde','Moradia','Lazer','Educação'].map(x=>`<option>${x}</option>`).join('')}</datalist></label><label class="fld"><span>Pagamento</span><select id="gpay"><option></option>${['Pix','Débito','Crédito','Dinheiro','Cartão DUNE'].map(x=>`<option>${x}</option>`).join('')}</select></label></div>
  <label class="fld"><span>Comprovante</span><input type="file" accept="image/*" id="gfile"></label></details>`,
  foot:`<button class="btn dune" data-a="gSave">Salvar gasto</button>`};
};
A.gParse=()=>{const t=val('tx-gasto');if(!t)return;const p=parseExpense(t);SH.args.pre=p;SH.args.from=t;renderSheet()};
A.gArea=(ds)=>{SH.args.pre=Object.assign(SH.args.pre||{},{area:ds.v,value:num(val('gv')),desc:val('gdesc'),date:val('gd'),cat:val('gcat')});document.querySelectorAll('#garea button').forEach(b=>b.classList.toggle('on',b.dataset.v===ds.v))};
A.gSave=async()=>{
  const v=num(val('gv')),desc=val('gdesc'),area=(SH.args.pre||{}).area;
  if(!v){toast('Informe o valor');return}if(!desc){toast('Informe a descrição');return}if(!area){toast('Escolha Pessoal ou DUNE');return}
  const s={id:uid(),area,desc,value:v,date:val('gd')||D.today(),cat:val('gcat'),pay:val('gpay'),sync:{mmv:'ok',claude:'demo',fin:'demo'},src:SH.args.from||''};
  const f=$('#gfile')&&$('#gfile').files[0];if(f){try{const pid='rc_'+s.id;PH[pid]=await fileToImg(f,900);savePhotos();s.receipt=pid}catch(e){}}
  S.fin.spend.push(s);save({quiet:true});closeSheet();
  const c=finCalc(area);toast(`Gasto salvo · ${area==='dune'?'DUNE':'Pessoal'}: ${brl(c.spent)} no mês`);
};
/* contas */
SHEETS.bill=({id})=>{const b=id?S.bills.find(x=>x.id===id):{area:'pessoal',desc:'',value:'',due:D.today(),status:'aberto',cat:'',rec:'única'};
  const al=b.alerts||{day:true,d7:true};
  return {title:id?esc(b.desc):'Nova conta',body:`${id?`<div class="card"><div class="row"><div class="grow">${areaPill(b.area)} <span class="pill ${b.status==='pago'?'ok':''}">${b.status==='pago'?'paga em '+D.short(b.paidAt):'em aberto'}</span></div><div class="big num">${brl(b.value)}</div></div><small class="mut">Vencimento: ${D.long(b.due)}</small></div>`:''}
  <label class="fld"><span>Descrição</span><input id="bd" value="${esc(b.desc)}"></label><div class="grid2"><label class="fld"><span>Valor</span><input id="bv" inputmode="decimal" value="${b.value?String(b.value).replace('.',','):''}"></label><label class="fld"><span>Vencimento</span><input type="date" id="bdu" value="${b.due}"></label></div>
  <div class="grid2"><label class="fld"><span>Área</span><select id="ba"><option value="pessoal" ${b.area==='pessoal'?'selected':''}>Pessoal</option><option value="dune" ${b.area==='dune'?'selected':''}>DUNE</option></select></label><label class="fld"><span>Tipo</span><select id="br">${['única','mensal','parcela'].map(x=>`<option ${b.rec===x?'selected':''}>${x}</option>`).join('')}</select></label></div>
  <div class="sec"><h3>Avisos</h3></div><label class="row" style="padding:6px 0"><input type="checkbox" id="bal1" ${al.day?'checked':''}> No dia do vencimento</label><label class="row" style="padding:6px 0"><input type="checkbox" id="bal7" ${al.d7?'checked':''}> 7 dias antes</label>`,
  foot:id?`${delBtn('billDel',id)}<button class="btn line" data-a="billSave" data-id="${id}">Salvar</button><button class="btn ${b.status==='pago'?'sec2':'pes'}" data-a="billPay" data-id="${id}">${b.status==='pago'?'Desfazer pagamento':'Marcar como paga'}</button>`:`<button class="btn" data-a="billSave">Salvar conta</button>`};
};
A.openBill=(ds)=>openSheet('bill',{id:ds.id});
A.billSave=(ds)=>{let b=ds.id?S.bills.find(x=>x.id===ds.id):null;if(!b){b={id:uid(),status:'aberto'};S.bills.push(b)}Object.assign(b,{desc:val('bd')||'Conta',value:num(val('bv')),due:val('bdu')||D.today(),area:val('ba'),rec:val('br'),alerts:{day:val('bal1'),d7:val('bal7')}});save({quiet:true});closeSheet();toast('Conta salva')};
A.billPay=(ds)=>{const b=S.bills.find(x=>x.id===ds.id);
  if(b.status==='pago'){b.status='aberto';b.paidAt=null;if(b.nextId)S.bills=S.bills.filter(x=>x.id!==b.nextId),b.nextId=null}
  else{b.status='pago';b.paidAt=D.today();if(b.rec==='mensal'&&!b.nextId){const d=new Date(b.due+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);const n={...b,id:uid(),status:'aberto',paidAt:null,due:d.toISOString().slice(0,10),nextId:null};S.bills.push(n);b.nextId=n.id}}
  save({quiet:true});closeSheet();toast(b.status==='pago'?`Paga · em aberto agora: ${brl(finCalc('tudo').billsOpen)}`:'Pagamento desfeito')};
SHEETS.income=({id})=>{const i=id?S.fin.inc.find(x=>x.id===id):{desc:'',value:'',date:D.today(),area:U.finArea==='tudo'?'dune':U.finArea,status:'previsto'};
  return {title:id?'Receita':'Nova receita',body:`<label class="fld"><span>Descrição</span><input id="id1" value="${esc(i.desc)}"></label><div class="grid2"><label class="fld"><span>Valor</span><input id="iv" inputmode="decimal" value="${i.value?String(i.value).replace('.',','):''}" placeholder="a confirmar"></label><label class="fld"><span>Data</span><input type="date" id="idt" value="${i.date}"></label></div><div class="grid2"><label class="fld"><span>Área</span><select id="ia">${[['dune','DUNE'],['extra','Extras · Diana (CNPJ DUNE)'],['pessoal','Pessoal']].map(([k,l])=>`<option value="${k}" ${i.area===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="fld"><span>Status</span><select id="is"><option value="previsto" ${i.status==='previsto'?'selected':''}>Previsto</option><option value="recebido" ${i.status==='recebido'?'selected':''}>Recebido</option></select></label></div>`,foot:`${id?delBtn('incDel',id):''}<button class="btn" data-a="incSave" data-id="${id||''}">Salvar</button>`}};
A.incSave=(ds)=>{let i=ds.id?S.fin.inc.find(x=>x.id===ds.id):null;if(!i){i={id:uid()};S.fin.inc.push(i)}Object.assign(i,{desc:val('id1')||'Receita',value:num(val('iv')),date:val('idt'),area:val('ia'),status:val('is')});save({quiet:true});closeSheet();toast('Receita salva')};
A.incDel=(ds)=>{if(!delOk(ds))return;S.fin.inc=S.fin.inc.filter(x=>x.id!==ds.id);save({quiet:true});closeSheet()};
SHEETS.debt=({id})=>{const d=S.debts.find(x=>x.id===id);return {title:esc(d.name),body:`<div class="card"><small class="mut">Saldo devedor</small><div class="big num">${brl(d.balance)}</div><small class="mut">Parcela prevista ${brl(d.monthly||d.mPlan||0)}</small></div>
  <div class="grid2"><label class="fld"><span>Valor pago</span><input id="dv" inputmode="decimal" value="${String(d.monthly||d.mPlan||0).replace('.',',')}"></label><label class="fld"><span>Tipo</span><select id="dk"><option value="parcela">Parcela</option><option value="adiantamento">Adiantamento</option></select></label></div>
  <div class="sec"><h3>Pagamentos</h3></div>${d.pays.slice().reverse().map(p=>`<div class="kv"><span>${D.short(p.date)} · ${p.kind}</span><b class="num">${brl(p.value)}</b></div>`).join('')||'<p class="empty">Nenhum ainda.</p>'}`,foot:`${d.src==='gestao'?'':delBtn('debtDel',id)}<button class="btn pes" data-a="debtPay" data-id="${id}">Registrar pagamento</button>`}};
A.debtPay=(ds)=>{const d=S.debts.find(x=>x.id===ds.id),v=num(val('dv'));if(!v)return;d.pays.push({date:D.today(),value:v,kind:val('dk')});d.balance=Math.max(0,Math.round((d.balance-v)*100)/100);save({quiet:true});renderSheet();toast('Saldo atualizado: '+brl(d.balance))};

/* ---------- DESEJOS ---------- */
SCREENS.desejos=()=>{
  const f=U.wishF,ws=S.wishes.filter(w=>f==='todos'||w.term===f);
  return backTop('Lista de Desejos',`<button class="btn sm dune" data-a="sheet" data-v="wishEdit">+ Desejo</button>`)+`<div class="chips">${[['todos','Todos'],['curto','Curto prazo'],['medio','Médio prazo'],['longo','Longo prazo']].map(([k,l])=>`<button class="chip ${f===k?'on':''}" data-a="setU" data-k="wishF" data-v="${k}">${l}</button>`).join('')}</div>
  <div class="gal" style="margin-top:12px">${ws.map(w=>`<button class="wc" data-a="openWish" data-id="${w.id}">${w.photos&&w.photos.length?`<img src="${phSrc(w.photos[0])}" alt="">`:`<div style="aspect-ratio:4/3;background:var(--soft)"></div>`}<div><b>${esc(w.name)}</b><small class="mut tiny">${w.goal&&w.goal.on?`${Math.round(w.goal.saved/(w.goal.value||w.value||1)*100)}% guardado`:w.value?brl(w.value):'sem valor definido'}${w.showToday?' · em Hoje':''}</small></div></button>`).join('')}</div>
  ${ws.length?'':'<p class="empty">Nenhum desejo neste filtro.</p>'}
  <label class="row card" style="margin-top:14px"><input type="checkbox" data-ch="carToggle" ${S.set.carousel?'checked':''}><span class="grow">Mostrar carrossel em Hoje</span></label>`;
};
A.carToggle=(ds,el)=>{S.set.carousel=el.checked;save({quiet:true})};
A.openWish=(ds)=>openSheet('wish',{id:ds.id});
function goalForecast(w,monthly,target){
  const g=w.goal,total=g.value||w.value||0,rem=Math.max(0,total-g.saved);monthly=monthly===undefined?(g.paused?0:g.monthly):monthly;target=target===undefined?g.target:target;
  const months=monthly>0?Math.ceil(rem/monthly):null;const when=months!==null?D.add(D.today(),months*30.4):null;
  let need=null;if(target){const m=Math.max(1,Math.round(D.diff(D.today(),target)/30.4));need=rem/m}
  return {total,rem,months,when,need,pct:total?Math.min(100,g.saved/total*100):0};
}
SHEETS.wish=({id})=>{
  const w=S.wishes.find(x=>x.id===id),g=w.goal;let b=`${(w.photos||[]).length?`<img src="${phSrc(w.photos[0])}" alt="" style="width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:16px">`:''}${(w.photos||[]).length>1?`<div class="thumbs" style="margin-top:8px">${w.photos.slice(1).map(p=>`<img src="${phSrc(p)}" alt="">`).join('')}</div>`:''}
   <div class="row wrap" style="gap:6px;margin-top:10px"><span class="pill">${{curto:'Curto',medio:'Médio',longo:'Longo'}[w.term]} prazo</span><span class="pill">prioridade ${esc(w.prio)}</span>${w.value?`<span class="pill">${brl(w.value)}</span>`:''}${w.target?`<span class="pill">até ${D.short(w.target)}/${w.target.slice(2,4)}</span>`:''}</div>
   ${w.why?`<p style="margin:10px 0 0"><span class="mut tiny">Por que importa</span><br>${esc(w.why)}</p>`:''}${w.link?`<p class="tiny"><a href="${esc(w.link)}" target="_blank" rel="noopener">Abrir link</a></p>`:''}`;
  if(g&&g.on){const fc=goalForecast(w);const ym=D.today().slice(0,7),month=(g.contribs||[]).filter(c=>inMonth(c.date,ym)).reduce((a,c)=>a+c.value,0);
    b+=`<div class="sec"><h2>Meta financeira</h2></div><div class="card" style="padding:0;overflow:hidden"><div style="display:flex;gap:12px;padding:12px">${(w.photos||[]).length?`<img src="${phSrc(w.photos[0])}" alt="" style="width:64px;height:64px;border-radius:12px;object-fit:cover">`:''}<div class="grow"><div class="big num" id="wsaved">${brl(g.saved)}</div><small class="mut">guardados de ${brl(fc.total)} · faltam <b>${brl(fc.rem)}</b></small></div></div>
    <div style="padding:0 12px 12px"><div class="bar" style="height:12px"><i id="wbar" style="width:${fc.pct}%"></i></div>
    <div class="kv" style="margin-top:8px"><span>Previsão com ${g.paused?'aporte pausado':brl(g.monthly)+'/mês'}</span><b>${fc.when?`${MESL[+fc.when.slice(5,7)-1]} de ${fc.when.slice(0,4)}`:'sem previsão'}</b></div>
    ${fc.need!==null?`<div class="kv"><span>Para chegar até ${D.short(g.target)}/${g.target.slice(2,4)}</span><b class="num">${brl(fc.need)}/mês</b></div>`:''}
    <div class="kv"><span>Reservado este mês</span><b class="num">${brl(month)} de ${brl(g.paused?0:g.monthly)}</b></div></div></div>
    <div class="row" style="gap:8px;margin-top:10px"><button class="btn pes grow" data-a="wAporte" data-id="${id}" data-v="50">+ R$ 50</button><input id="wav" inputmode="decimal" placeholder="Outro valor" style="flex:1"><button class="btn sm sec2" data-a="wAporte" data-id="${id}">Aportar</button></div>
    <div class="sec"><h3>Simular</h3></div><div class="card"><div class="row"><span class="grow">Aporte mensal</span><b class="num" id="wsm">${brl(g.monthly)}</b></div><input type="range" min="0" max="${Math.max(3000,g.monthly*3)}" step="50" value="${g.monthly}" data-in="wSim" data-id="${id}">
    <label class="fld"><span>Data-alvo (opcional)</span><input type="date" id="wst" value="${g.target||''}" data-ch="wSimT" data-id="${id}"></label><p class="tiny" id="wsr" style="margin:8px 0 0"></p><p class="tiny mut" id="wsr2" style="margin:4px 0 0"></p>
    <div class="row" style="gap:8px;margin-top:8px"><button class="btn sm" data-a="wApplySim" data-id="${id}">Usar estes valores</button><button class="btn sm sec2" data-a="wPause" data-id="${id}">${g.paused?'Retomar aporte':'Pausar aporte'}</button></div></div>
    <div class="sec"><h3>Aportes</h3></div>${(g.contribs||[]).slice().reverse().map(c=>`<div class="kv"><span>${D.short(c.date)}</span><b class="num">${brl(c.value)}</b></div>`).join('')||'<p class="empty">Nenhum aporte ainda.</p>'}`;
  }else if(SH.args.goalForm){b+=`<div class="sec"><h2>Transformar em meta financeira</h2></div><div class="grid2"><label class="fld"><span>Valor estimado</span><input id="gfv" inputmode="decimal" value="${w.value?String(w.value).replace('.',','):''}"></label><label class="fld"><span>Já guardei</span><input id="gfs" inputmode="decimal" placeholder="0"></label></div><div class="grid2"><label class="fld"><span>Separar por mês</span><input id="gfm" inputmode="decimal" placeholder="200"></label><label class="fld"><span>Data-alvo (opcional)</span><input type="date" id="gft" value="${w.target||''}"></label></div>`}
  const foot=g&&g.on?`<button class="btn line" data-a="sheet" data-v="wishEdit" data-id="${id}">Editar desejo</button>`:SH.args.goalForm?`<button class="btn pes" data-a="wGoalOn" data-id="${id}">Ativar meta</button>`:`<button class="btn line" data-a="sheet" data-v="wishEdit" data-id="${id}">Editar</button><button class="btn pes" data-a="wGoalForm">Transformar em meta</button>`;
  return {title:esc(w.name),body:b,foot,after(){if(g&&g.on)A.wSim(document.querySelector('[data-in="wSim"]'))}};
};
A.wGoalForm=()=>{SH.args.goalForm=true;renderSheet();setTimeout(()=>{const e=$('.sh-b');e.scrollTop=e.scrollHeight},50)};
A.wGoalOn=(ds)=>{const w=S.wishes.find(x=>x.id===ds.id),v=num(val('gfv'));if(!v){toast('Informe o valor estimado');return}w.value=w.value||v;const s=num(val('gfs'));w.goal={on:true,value:v,saved:s,monthly:num(val('gfm')),target:val('gft'),paused:false,contribs:s?[{date:D.today(),value:s,initial:true}]:[]};SH.args.goalForm=false;save({quiet:true});renderSheet();toast('Meta financeira ativada')};
A.wAporte=(ds)=>{const w=S.wishes.find(x=>x.id===ds.id),v=ds.v?+ds.v:num(val('wav'));if(!v){toast('Informe o valor');return}w.goal.saved=Math.round((w.goal.saved+v)*100)/100;w.goal.contribs.push({date:D.today(),value:v});save({quiet:true});renderSheet();toast(`Aporte de ${brl(v)} reservado`)};
A.wSim=(el)=>{if(!el)return;const w=S.wishes.find(x=>x.id===el.dataset.id),m=+el.value,t=val('wst');$('#wsm').textContent=brl(m)+'/mês';const fc=goalForecast(w,m,t);
  $('#wsr').innerHTML=fc.when?`Com ${brl(m)}/mês você chega lá em <b>${MESL[+fc.when.slice(5,7)-1]} de ${fc.when.slice(0,4)}</b> (${fc.months} meses).`:'Sem aporte mensal não há previsão.';
  const c=finCalc('pessoal'),sobra=c.sobra+((w.goal.paused?0:w.goal.monthly)-m);
  $('#wsr2').innerHTML=(fc.need!==null?`Para a data-alvo seriam ${brl(fc.need)}/mês. `:'')+`Sobra pessoal no mês com este aporte: <b style="color:${sobra<0?'var(--red)':'var(--ok)'}">${brl(sobra)}</b>.`};
A.wSimT=()=>A.wSim(document.querySelector('[data-in="wSim"]'));
A.wApplySim=(ds)=>{const w=S.wishes.find(x=>x.id===ds.id);w.goal.monthly=+document.querySelector('[data-in="wSim"]').value;w.goal.target=val('wst');save({quiet:true});renderSheet();toast('Meta ajustada')};
A.wPause=(ds)=>{const w=S.wishes.find(x=>x.id===ds.id);w.goal.paused=!w.goal.paused;save({quiet:true});renderSheet();toast(w.goal.paused?'Aporte pausado. O valor guardado continua.':'Aporte retomado')};
SHEETS.wishEdit=({id})=>{const w0=id?S.wishes.find(x=>x.id===id):{name:'',photos:[],term:'curto',prio:'média',value:'',target:'',why:'',link:'',showToday:true};const w=SH.args._draft?Object.assign({},w0,SH.args._draft):w0;SH.args.photos=SH.args.photos||[...(w.photos||[])];
  return {title:id?'Editar desejo':'Novo desejo',body:`<div class="thumbs" id="wph">${SH.args.photos.map((p,i)=>`<button data-a="wRmPh" data-i="${i}" style="position:relative"><img src="${phSrc(p)}" alt=""><span style="position:absolute;top:2px;right:2px;background:#fff;border-radius:50%;width:22px;height:22px;display:grid;place-items:center">${IC.x}</span></button>`).join('')}<label style="width:76px;height:76px;border-radius:12px;border:2px dashed var(--line);display:grid;place-items:center;color:var(--ink3);position:relative;overflow:hidden">${IC.plus}<input type="file" accept="image/*" multiple data-ch="wPhotos" style="position:absolute;inset:0;opacity:0" aria-label="Adicionar fotos"></label></div>
  <p class="tiny mut">No iPhone, escolha da galeria ou tire uma foto.</p>
  <label class="fld"><span>Nome</span><input id="wn" value="${esc(w.name)}" placeholder="Ex.: meu carro"></label>
  <label class="fld"><span>Link (opcional)</span><input id="wl" inputmode="url" value="${esc(w.link)}" placeholder="Cole um link"></label>
  <div class="grid2"><label class="fld"><span>Prazo</span><select id="wt">${[['curto','Curto'],['medio','Médio'],['longo','Longo']].map(([k,l])=>`<option value="${k}" ${w.term===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="fld"><span>Prioridade</span><select id="wp">${['alta','média','baixa'].map(k=>`<option ${w.prio===k?'selected':''}>${k}</option>`).join('')}</select></label></div>
  <div class="grid2"><label class="fld"><span>Valor estimado (opcional)</span><input id="wv" inputmode="decimal" value="${w.value?String(w.value).replace('.',','):''}"></label><label class="fld"><span>Data-alvo (opcional)</span><input type="date" id="wd" value="${w.target||''}"></label></div>
  <label class="fld"><span>Por que isso importa pra mim</span><textarea id="wy">${esc(w.why)}</textarea></label>
  <label class="row fld"><input type="checkbox" id="ws" ${w.showToday?'checked':''}><span style="margin:0">Mostrar no carrossel de Hoje</span></label>`,
  foot:`${id?`<button class="btn line" data-a="wDel" data-id="${id}">Excluir</button>`:''}<button class="btn dune" data-a="wSave" data-id="${id||''}">Salvar</button>`};
};
A.wPhotos=async(ds,el)=>{for(const f of [...el.files].slice(0,4)){try{const pid='ph_'+uid();PH[pid]=await fileToImg(f,720);SH.args.photos.push(pid)}catch(e){toast('Não consegui ler a imagem')}}savePhotos();keepWishForm();renderSheet()};
A.wRmPh=(ds)=>{SH.args.photos.splice(+ds.i,1);keepWishForm();renderSheet()};
function keepWishForm(){SH.args._draft={name:val('wn'),link:val('wl'),term:val('wt'),prio:val('wp'),value:val('wv'),target:val('wd'),why:val('wy'),showToday:val('ws')}}
A.wSave=(ds)=>{const name=val('wn');if(!name){toast('Dê um nome ao desejo');return}let w=ds.id?S.wishes.find(x=>x.id===ds.id):null;if(!w){w={id:uid(),goal:{on:false,saved:0,monthly:0,target:'',paused:false,contribs:[]}};S.wishes.push(w)}
  Object.assign(w,{name,photos:SH.args.photos,link:val('wl'),term:val('wt'),prio:val('wp'),value:num(val('wv')),target:val('wd'),why:val('wy'),showToday:val('ws')});if(w.showToday)S.set.carousel=true;save({quiet:true});closeSheet();openSheet('wish',{id:w.id});toast('Desejo salvo')};
A.wDel=(ds)=>{S.wishes=S.wishes.filter(w=>w.id!==ds.id);save({quiet:true});closeSheet()};

/* ---------- NOTIFICAÇÕES ---------- */
SCREENS.notif=()=>{
  const P=S.notif,L=notifList(),up=L.filter(n=>!n.past),tg=(k,l)=>`<label class="row" style="padding:9px 0;border-top:1px solid var(--line)"><span class="grow">${l}</span><input type="checkbox" data-ch="nPref" data-k="${k}" ${P[k]?'checked':''}></label>`,tm=(k,l)=>`<label class="row" style="padding:6px 0"><span class="grow tiny mut">${l}</span><input type="time" style="width:120px" data-ch="nPref" data-k="${k}" value="${P[k]}"></label>`;
  return backTop('Avisos')+`<p class="note demo">${demo('avisos simulados')} Aqui você testa preferências, a central e a navegação. As notificações reais no iPhone chegam pela versão publicada (PWA + Web Push), no fuso America/Bahia.</p>
  <div class="sec"><h2>Próximos avisos</h2></div><div class="card">${up.slice(0,10).map(n=>`<div class="li"><span class="tm" style="width:64px;font-size:12.5px">${D.short(n.when.slice(0,10))}<br>${n.when.slice(11)}</span><span class="t"><b>${esc(n.title)}</b><small class="mut">${esc(n.cat)} · ${esc(n.body)}</small></span><button class="btn sm sec2" data-a="nSim" data-k="${esc(n.k)}">Simular</button></div>`).join('')||'<p class="empty">Nenhum aviso pendente.</p>'}</div>
  <div class="sec"><h2>Atualizações dos avisos</h2></div><div class="card">${S.nlog.slice(0,8).map(l=>`<div class="kv"><span><span class="pill ${l.st==='cancelado'?'bad':'demo'}">${l.st}</span> ${esc(l.title)}</span><small class="mut tiny" style="text-align:right">${esc(l.why)}</small></div>`).join('')||'<p class="empty">Quando você concluir, pagar ou remarcar algo, o aviso pendente é cancelado ou reagendado aqui, sem repetir.</p>'}</div>
  <div class="sec"><h2>O que receber</h2></div><div class="card">${tg('bills','Contas a pagar')}${tg('billDay','· no dia do vencimento')}${tg('bill7','· 7 dias antes')}${tm('billTime','Horário dos avisos de contas')}${tg('rec','Lembretes de gravação')}<label class="row" style="padding:6px 0"><span class="grow tiny mut">Antecedência (min)</span><input inputmode="numeric" style="width:90px" data-ch="nPref" data-k="recLead" value="${P.recLead}"></label>${tg('del','Entregas')}${tg('tasks','Tarefas')}${tm('taskTime','Horário de entregas e tarefas')}${tg('summary','Resumo das pendências no fim do dia')}${tm('sumTime','Horário do resumo')}${tg('ckOn','Cobrança das metas (check-in)')}${tm('ckTime','Horário do check-in')}${tg('openRem','Lembrete se eu não entrar no app no dia')}${tm('openTime','Horário desse lembrete')}${tg('goalPrompt','Pedir a meta no dia 1º (mês, trimestre e semestre)')}${tm('goalTime','Horário do pedido de meta')}${tg('hideVal','Ocultar valores na tela bloqueada')}</div>
  <div class="sec"><h2>No iPhone (após publicar)</h2></div><div class="card"><ol class="tiny" style="margin:0;padding-left:18px;line-height:1.7"><li>Abra o MMV publicado no Safari e toque em Compartilhar › Adicionar à Tela de Início.</li><li>Abra pelo ícone e toque em <b>Ativar notificações</b>.</li><li>Use <b>Enviar notificação de teste</b> com o app fechado.</li></ol>
  <div class="row wrap" style="gap:8px;margin-top:10px"><button class="btn sm" data-a="nTest">Enviar notificação de teste</button><button class="btn sm sec2" data-a="nOff">${P.off?'Reativar':'Desativar'} notificações</button></div></div>`;
};
A.nPref=(ds,el)=>{const k=ds.k;S.notif[k]=el.type==='checkbox'?el.checked:(k==='recLead'?num(el.value):el.value);U.keepScroll=true;save()};
A.nSim=(ds)=>{const n=notifList().find(x=>x.k===ds.k);if(n)showBanner(n)};
A.nTest=()=>showBanner({title:'Notificação de teste do MMV',body:'Toque para abrir o checklist de hoje (demonstração).',open:['pend']});
A.nOff=()=>{S.notif.off=!S.notif.off;save();toast(S.notif.off?'Notificações desativadas (simulado)':'Notificações ativadas (simulado)')};
let banT;
function showBanner(n){const el=$('#ban');el.innerHTML=`<span class="ic">MMV</span><span class="grow"><b style="font-weight:600;font-size:14px">${esc(n.title)}</b><br><small class="mut">${esc(S.notif.hideVal&&/R\$/.test(n.body)?'Toque para ver':n.body)}</small><br><span class="pill demo" style="margin-top:4px">simulado · toque para abrir</span></span>`;el.dataset.open=JSON.stringify(n.open||[]);el.classList.add('on');clearTimeout(banT);banT=setTimeout(()=>el.classList.remove('on'),6000)}
function openTarget(o){$('#ban').classList.remove('on');if(!o||!o.length)return;if(SH)closeSheetSoft(),$('#sheet').classList.remove('on'),$('#scrim').classList.remove('on');
  if(o[0]==='bill')openSheet('bill',{id:o[1]});else if(o[0]==='task')openSheet('task',{id:o[1]});else if(o[0]==='goal')openSheet('goal',{k:o[1]});else if(o[0]==='check')openSheet('goalCheck',{id:o[1]});else if(o[0]==='pend'){U.page=null;U.tab='hoje';U.date=D.today();U.showAll=true;render();window.scrollTo(0,0)}}

/* ---------- MAIS ---------- */
const MAIS=[['planejamento','Planejamento','Metas do semestre, trimestre e mês'],['projetos','Projetos','DUNE, Extras, SOS Stories e Pessoal'],['conteudo','Conteúdo','Banco de ideias e produção'],['notas','Notas e capturas','Busca em ideias, notas e relatos'],['leitura','Leitura','Caderno de Leitura'],['treinos','Treinos','Cronograma e histórico'],['fe','Fé e Gratidão','Oração, Bíblia e agradecimentos'],['desejos','Lista de Desejos','Galeria e metas financeiras'],['revisao','Revisão','Semana, evolução e ajustes'],['notif','Avisos','Central de notificações'],['conexoes','Conexões','O que funciona e o que conectar'],['config','Configurações','Código, expediente, checklist e dados']];
const MAIS_IC={"planejamento": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><circle cx=\"12\" cy=\"12\" r=\"4.5\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"currentColor\"/></svg>", "#B07A45", "#F3E6D8"], "projetos": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3.5 7.5a2 2 0 012-2h4l2 2h7a2 2 0 012 2v7.5a2 2 0 01-2 2h-13a2 2 0 01-2-2z\"/></svg>", "#B07A45", "#F3E6D8"], "conteudo": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"6\" width=\"13\" height=\"12\" rx=\"2.5\"/><path d=\"M16 10.5l4.5-2.5v8L16 13.5\"/></svg>", "#8C6E8F", "#EFE6F0"], "notas": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 3.5h9l3.5 3.5v13.5H6z\"/><path d=\"M14.5 3.5V7.5h4M9 12h6.5M9 15.5h4.5\"/></svg>", "#B07A45", "#F3E6D8"], "leitura": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 5.5C6.5 4 9.5 4 12 6c2.5-2 5.5-2 8-.5V19c-2.5-1.5-5.5-1.5-8 .5-2.5-2-5.5-2-8-.5z\"/><path d=\"M12 6v13.5\"/></svg>", "#6F9676", "#E3EEE4"], "treinos": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 8v8M17 8v8M4.5 10v4M19.5 10v4M7 12h10\"/></svg>", "#6F9676", "#E3EEE4"], "fe": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3.5v17M7 8.5h10\"/></svg>", "#B8913F", "#F6EDD8"], "desejos": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20s-7.5-4.6-7.5-10A4.3 4.3 0 0112 7.3 4.3 4.3 0 0119.5 10c0 5.4-7.5 10-7.5 10z\"/></svg>", "#7A2E3A", "#F2DEE1"], "revisao": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 20h16\"/><rect x=\"5.5\" y=\"12\" width=\"3\" height=\"5.5\" rx=\"1\"/><rect x=\"10.5\" y=\"8\" width=\"3\" height=\"9.5\" rx=\"1\"/><rect x=\"15.5\" y=\"4.5\" width=\"3\" height=\"13\" rx=\"1\"/></svg>", "#6F9676", "#E3EEE4"], "notif": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 16V11a6 6 0 0112 0v5l1.5 2h-15zM10 20.5a2 2 0 004 0\"/></svg>", "#7A2E3A", "#F2DEE1"], "conexoes": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 14a4 4 0 005.7 0l3-3a4 4 0 00-5.7-5.7l-1 1\"/><path d=\"M14 10a4 4 0 00-5.7 0l-3 3a4 4 0 005.7 5.7l1-1\"/></svg>", "#6E625A", "#F4EEE6"], "config": ["<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7\"/></svg>", "#6E625A", "#F4EEE6"]};
SCREENS.mais=()=>`<div class="top"><h1>Mais</h1></div><div class="card" style="padding:4px 14px">${MAIS.map(([k,l,d])=>{const ic=MAIS_IC[k]||['','var(--ink2)','var(--soft)'];return `<button class="li" data-a="go" data-v="${k}"><span class="mic-ic" style="color:${ic[1]};background:${ic[2]}">${ic[0]}</span><span class="t"><b>${l}</b><small class="mut">${d}</small></span>${IC.r}</button>`}).join('')}</div><p class="tiny mut3" style="text-align:center;margin-top:18px">${persistLine()}</p>`;

/* ---------- NOTAS ---------- */
SCREENS.notas=()=>{const q=norm(U.q||'');const items=[...S.captures.map(c=>({id:c.id,t:c.type,text:c.text,d:c.at,sim:c.sim})),...S.closings.filter(c=>c.raw).map(c=>({t:'relato',text:c.raw,d:c.date}))].filter(x=>!q||norm(x.text).includes(q)).sort((a,b)=>a.d<b.d?1:-1);
  return backTop('Bloco de notas',`<button class="btn sm dune" data-a="capture">+ Nota</button>`)+`<input id="nq" type="search" placeholder="Buscar em notas, ideias e relatos…" value="${esc(U.q||'')}" data-in="nSearch">
  <div style="margin-top:12px" id="nlist">${items.map(x=>`<button class="card note-c" ${x.id?`data-a="sheet" data-v="noteEdit" data-id="${x.id}"`:''}><small class="mut">${esc({nota:'Nota',ideia:'Ideia',relato:'Relato',tarefa:'Tarefa',gasto:'Gasto'}[x.t]||x.t)} · ${D.lbl(x.d)}${x.sim?' · transcrição simulada':''}</small><p>${esc(x.text)}</p></button>`).join('')||'<p class="empty">Nada encontrado. Toque em Notas, na barra de baixo, para anotar.</p>'}</div>`};
SHEETS.noteEdit=({id})=>{const c=S.captures.find(x=>x.id===id);return {title:'Nota',body:`<small class="mut">${esc(D.long(c.at))}</small><textarea id="ne" style="min-height:220px;margin-top:8px">${esc(c.text)}</textarea>${c.raw&&c.raw!==c.text?`<p class="note">Transcrição original: “${esc(c.raw)}”</p>`:''}`,foot:`<button class="btn line" data-a="noteDel" data-id="${id}">Excluir</button><button class="btn dune" data-a="noteSave" data-id="${id}">Salvar</button>`}};
A.noteSave=(ds)=>{const c=S.captures.find(x=>x.id===ds.id);c.text=val('ne');save({quiet:true});closeSheet();toast('Nota salva')};
A.noteDel=(ds)=>{S.captures=S.captures.filter(x=>x.id!==ds.id);save({quiet:true});closeSheet();toast('Nota excluída')};
A.nSearch=(el)=>{U.q=el.value;clearTimeout(A._q);A._q=setTimeout(()=>{render();const e=$('#nq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},350)};

/* ---------- LEITURA ---------- */
SCREENS.leitura=()=>{const b=curBook(),T=D.today();
  const wk=[...Array(7)].map((_,i)=>D.add(T,i-6)),st=d=>readStats(d);
  const mon=S.readS.filter(r=>D.diff(r.date,T)<30),week=S.readS.filter(r=>D.diff(r.date,T)<7);
  const sum=(a,k)=>Math.round(a.reduce((x,r)=>x+r[k],0));
  let h=backTop('Caderno de Leitura');
  h+=`<button class="btn pes" style="width:100%;margin-bottom:10px" data-a="sheet" data-v="leitura" data-d="${T}">${IC.play} ${S.readT?'Leitura em andamento · abrir':'Iniciar leitura do dia'}</button>`;
  if(!b)h+=`<div class="card"><p class="empty">Nenhum livro cadastrado. O cronômetro funciona mesmo assim, para livro físico ou leitura em outro lugar. Para acompanhar páginas, adicione o livro na fila.</p></div>`;
  if(b)h+=`<div class="card"><small class="mut">Lendo agora</small><h2 style="margin-top:2px">${esc(b.title)}</h2><small class="mut">${esc(b.author)}</small><div class="row" style="margin-top:10px"><div class="bar grow"><i style="width:${Math.round(b.current/b.pages*100)}%"></i></div><span class="num tiny">pág. ${b.current}/${b.pages}</span></div><div class="row" style="gap:8px;margin-top:12px">${b.demo||b.pdf?`<button class="btn sm pes grow" data-a="openReader">Abrir e retomar · pág. ${Math.min(b.current+1,b.pages)}</button>`:`<button class="btn sm pes grow" data-a="sheet" data-v="leitura" data-d="${T}">Lançar leitura manual</button>`}${b.demo?'':`<button class="btn sm sec2" data-a="bookDone" data-id="${b.id}">Terminei</button>`}</div>
   <div class="pdfbox">${b.pdf?`<div class="row"><span class="pdf-ic">PDF</span><span class="grow"><b style="font-weight:500">${esc(b.pdf.name)}</b><br><small class="mut">${(b.pdf.size/1048576).toFixed(1)} MB · guardado ${b.pdf.store==='conta'?'na sua conta Claude (abre em qualquer aparelho)':'só neste aparelho'}</small></span></div>
     <div class="row" style="gap:8px;margin-top:10px"><label class="btn sm line" style="position:relative;overflow:hidden">Trocar PDF<input type="file" accept="application/pdf,.pdf" data-ch="pdfPick" data-id="${b.id}" style="position:absolute;inset:0;opacity:0"></label><button class="btn sm line" data-a="pdfDel" data-id="${b.id}">Apagar PDF</button></div>`
     :`<b style="font-weight:500">Ler dentro do MMV</b><p class="tiny mut" style="margin:4px 0 10px">Escolha o PDF no app Arquivos (o Google Drive também aparece lá). O MMV acompanha páginas e tempo sozinho. Ao terminar o livro, o arquivo é apagado e ficam só as suas notas.</p><label class="btn sm dune" style="position:relative;overflow:hidden">Escolher PDF no iPhone<input type="file" accept="application/pdf,.pdf" data-ch="pdfPick" data-id="${b.id}" style="position:absolute;inset:0;opacity:0"></label>`}</div>
   <label class="fld"><span>Link do Drive (abrir direto pelo link chega na publicação)</span><div class="row" style="gap:8px"><input id="bl" inputmode="url" value="${esc(b.link||'')}" placeholder="https://drive.google.com/…"><button class="btn sm sec2" data-a="bookLink">Salvar</button></div></label>${b.link?`<a class="tiny" href="${esc(b.link)}" target="_blank" rel="noopener">Abrir no Drive</a>`:''}</div>`;
  h+=`<div class="sec"><h2>Evolução</h2></div><div class="grid2"><div class="card"><small class="mut">7 dias</small><div class="big">${sum(week,'pages')} pág.</div><small class="mut">${sum(week,'min')} min · ${week.length} sessões</small></div><div class="card"><small class="mut">30 dias</small><div class="big">${sum(mon,'pages')} pág.</div><small class="mut">${sum(mon,'min')} min · ${mon.length} sessões</small></div></div>
  <div class="card" style="margin-top:10px"><small class="mut">Minutos por dia</small>${barChart(wk.map(d=>({l:DOW[D.dow(d)],v:st(d).min,none:!S.readS.some(r=>r.date===d)})),'var(--pes)')}</div>`;
  h+=`<div class="sec"><h2>Notas e trechos</h2></div><div class="card">${S.books.flatMap(bk=>bk.notes.map((n,i)=>({bk,n,i}))).map(({bk,n,i})=>`<div class="li"><span class="t"><b style="font-weight:400">“${esc(n.text)}”</b><small class="mut">${esc(bk.title)} · pág. ${n.page}</small></span><button class="btn sm sec2" data-a="noteIdea" data-b="${bk.id}" data-i="${i}">Virar ideia</button></div>`).join('')||'<p class="empty">Destaque trechos no leitor.</p>'}</div>`;
  h+=`<div class="sec"><h2>Fila</h2></div><div class="card">${S.books.filter(x=>x.status!=='atual').map(x=>`<div class="li"><span class="t"><b>${esc(x.title)}</b><small class="mut">${esc(x.author)} · ${x.pages} pág. · ${x.status}</small></span>${x.status==='fila'?`<button class="btn sm sec2" data-a="bookStart" data-id="${x.id}">Começar</button>`:x.status==='lido'?`<span class="pill ok">lido ${x.finishedAt?D.short(x.finishedAt):''}</span>`:''}</div>`).join('')}
  <div class="grid2" style="margin-top:10px"><input id="nbt" placeholder="Título"><input id="nba" placeholder="Autor"></div><div class="row" style="gap:8px;margin-top:8px"><input id="nbp" inputmode="numeric" placeholder="Páginas"><button class="btn sm" data-a="bookAdd">Adicionar</button></div></div>
  <div class="card"><small class="mut">Critério para o check “Ler hoje”</small><div class="row" style="gap:8px;margin-top:8px"><select id="rr" data-ch="readRule"><option value="pages" ${S.set.readRule.type==='pages'?'selected':''}>Avançar páginas</option><option value="min" ${S.set.readRule.type==='min'?'selected':''}>Ler minutos</option></select><input id="rrv" inputmode="numeric" style="width:90px" value="${S.set.readRule.val}" data-ch="readRule"></div></div>`;
  return h;
};
function barChart(arr,color){const mx=Math.max(1,...arr.map(x=>x.v));return `<div class="chart" style="grid-template-columns:repeat(${arr.length},minmax(0,1fr))">${arr.map(x=>`<div><span class="num">${x.none?'':x.v||''}</span><i class="${x.none?'none':''}" style="height:${x.none?100:Math.max(3,x.v/mx*80)}%;background:${x.none?'':color}" title="${x.none?'sem registro':x.v}"></i><span>${x.l}</span></div>`).join('')}</div>`}
A.bookLink=()=>{curBook().link=val('bl');save();toast('Arquivo vinculado')};
A.bookStart=(ds)=>{S.books.forEach(b=>{if(b.status==='atual')b.status='fila'});S.books.find(b=>b.id===ds.id).status='atual';save()};
A.bookAdd=()=>{const t=val('nbt');if(!t)return;S.books.push({id:uid(),title:t,author:val('nba'),pages:num(val('nbp'))||200,current:0,status:'fila',link:'',notes:[]});save()};
A.readRule=()=>{S.set.readRule={type:val('rr'),val:num(val('rrv'))||1};save({quiet:true});toast('Critério salvo')};
A.noteIdea=(ds)=>{const bk=S.books.find(b=>b.id===ds.b),n=bk.notes[+ds.i];const c={id:uid(),original:n.text,profile:'ig_dune',format:'carrossel',stage:'captura',draft:null,post:'',plan:null,created:D.today(),ref:`${bk.title}, pág. ${n.page}`};S.contents.push(c);save({quiet:true});toast('Virou ideia de conteúdo',()=>{U.page='conteudo';openSheet('content',{id:c.id})},'Abrir')};

/* ---------- TREINOS ---------- */
SCREENS.treinos=()=>{const T=D.today(),wk=[...Array(7)].map((_,i)=>D.add(T,i-6));const ses=S.train.sessions.slice().sort((a,b)=>a.date<b.date?1:-1);
  const w7=S.train.sessions.filter(s=>D.diff(s.date,T)<7).reduce((a,s)=>a+s.min,0),m30=S.train.sessions.filter(s=>D.diff(s.date,T)<30).reduce((a,s)=>a+s.min,0);
  return backTop('Treinos')+`<button class="btn full pes" data-a="sheet" data-v="treino" data-d="${T}">Treino de hoje</button>
  <div class="grid2" style="margin-top:12px"><div class="card"><small class="mut">7 dias</small><div class="big">${w7} min</div></div><div class="card"><small class="mut">30 dias</small><div class="big">${m30} min</div></div></div>
  <div class="card" style="margin-top:10px"><small class="mut">Minutos por dia</small>${barChart(wk.map(d=>({l:DOW[D.dow(d)],v:S.train.sessions.filter(s=>s.date===d).reduce((a,s)=>a+s.min,0)})),'var(--pes)')}</div>
  <div class="sec"><h2>Cronograma semanal</h2></div><div class="card">${[1,2,3,4,5,6,0].map(d=>{const w=S.train.schedule[d];return `<div class="row" style="padding:6px 0;gap:8px"><b style="width:40px">${DOW[d]}</b><input id="sa${d}" value="${esc(w?w.act:'')}" placeholder="livre"><input id="sd${d}" inputmode="numeric" style="width:76px" value="${w?w.dur:''}" placeholder="min"></div>`}).join('')}<button class="btn sm" style="margin-top:8px" data-a="schedSave">Salvar cronograma</button></div>
  <div class="sec"><h2>Histórico</h2></div><div class="card">${ses.slice(0,14).map(s=>`<div class="kv"><span>${D.short(s.date)} · ${esc(s.act)}</span><span class="num">${s.min} min <small class="mut">${s.manual?(s.fromReport?'relato':'manual'):'cronômetro'}</small></span></div>`).join('')}</div>`};
A.schedSave=()=>{const s={};[0,1,2,3,4,5,6].forEach(d=>{const a=val('sa'+d);if(a)s[d]={act:a,dur:num(val('sd'+d))||30}});S.train.schedule=s;save();toast('Cronograma salvo')};

/* ---------- FÉ ---------- */
SCREENS.fe=()=>{const T=D.today(),wk=[...Array(7)].map((_,i)=>D.add(T,i-6));const pr=wk.filter(d=>isDone(d,'rezar')).length,bd=wk.filter(d=>S.habits.find(h=>h.id==='biblia').days.includes(D.dow(d))),br=bd.filter(d=>isDone(d,'biblia')).length;
  return backTop('Fé e Gratidão')+`<div class="card" style="padding:0 4px 0 0"><ul class="cl">${['rezar','biblia','gratidao'].map(k=>dayItems(T).find(i=>i.key===k)).filter(Boolean).map(ckRow).join('')}</ul></div>
  <div class="grid2" style="margin-top:12px"><div class="card"><small class="mut">Oração · 7 dias</small><div class="big">${pr}/7</div></div><div class="card"><small class="mut">Bíblia · dias escolhidos</small><div class="big">${br}/${bd.length}</div></div></div>
  <div class="card"><small class="mut">Dias de leitura da Bíblia</small><div class="days" style="margin-top:8px">${[0,1,2,3,4,5,6].map(d=>`<button class="${S.habits.find(h=>h.id==='biblia').days.includes(d)?'on':''}" data-a="bibDay" data-v="${d}"><b>${DOW[d]}</b></button>`).join('')}</div></div>
  <div class="sec"><h2>Agradecimentos</h2></div>${Object.keys(S.faith.grat).sort().reverse().slice(0,10).map(k=>`<div class="card"><small class="mut">${esc(D.lbl(k))}</small><div>${S.faith.grat[k].filter(Boolean).map(x=>'· '+esc(x)).join('<br>')}</div></div>`).join('')}
  <p class="note">A fé é acompanhada aqui, separada dos indicadores de produtividade.</p>`};
A.bibDay=(ds)=>{const h=S.habits.find(h=>h.id==='biblia'),d=+ds.v;h.days=h.days.includes(d)?h.days.filter(x=>x!==d):[...h.days,d];U.keepScroll=true;save()};

function extrasCard(){const T=D.today(),ym=T.slice(0,7),ex=S.fin.inc.filter(i=>i.area==='extra');
  const mes=ex.filter(i=>i.status==='recebido'&&inMonth(i.date,ym)).reduce((a,i)=>a+i.value,0),all=ex.filter(i=>i.status==='recebido').reduce((a,i)=>a+i.value,0),prev=ex.filter(i=>i.status==='previsto');
  const g=S.goals.find(x=>x.level==='smt'&&x.auto==='dividas');
  return `<div class="card" style="margin-top:12px"><small class="mut">Trabalhos por fora · caem no CNPJ da DUNE</small><div class="row" style="align-items:flex-end"><div class="grow"><div class="big num">${brl(mes)}</div><small class="mut">recebido em ${esc(D.mesNome(T))}</small></div><div style="text-align:right"><b class="num">${brl(all)}</b><br><small class="mut">no total</small></div></div>
  <div class="kv" style="margin-top:8px"><span>A receber</span><b>${prev.length?prev.map(p=>p.value?brl(p.value):'valor a confirmar').join(' + '):'—'}</b></div>
  ${g?`<div class="good" style="margin-top:10px"><b>Destino: ${esc(g.title)}</b>${goalViz(g)}</div>`:''}
  <button class="btn sm sec2" style="margin-top:10px" data-a="sheet" data-v="income">+ Receita extra</button></div>`}

A.projExtra=()=>{U.projA='extra';A.go({v:'projetos'})};

/* apagar com confirmação: o 1º toque pede confirmação, o 2º apaga */
let DELC=null;
function delBtn(act,id){const on=DELC===act+id;return `<button class="btn line" style="${on?'background:var(--red);color:#fff;border-color:var(--red)':'color:var(--red)'}" data-a="${act}" data-id="${id}">${on?'Toque de novo para apagar':'Apagar'}</button>`}
function delOk(ds){const k=ds.a+ds.id;if(DELC!==k){DELC=k;renderSheet();setTimeout(()=>{if(DELC===k){DELC=null;if(SH)renderSheet()}},4000);return false}DELC=null;return true}
A.billDel=(ds)=>{ds.a='billDel';if(!delOk(ds))return;S.bills=S.bills.filter(x=>x.id!==ds.id);save({quiet:true});closeSheet();toast('Conta apagada')};
A.debtDel=(ds)=>{ds.a='debtDel';if(!delOk(ds))return;S.debts=S.debts.filter(x=>x.id!==ds.id);save({quiet:true});closeSheet();toast('Dívida apagada')};
A.spendDel=(ds)=>{ds.a='spendDel';if(!delOk(ds))return;S.fin.spend=S.fin.spend.filter(x=>x.id!==ds.id);save({quiet:true});closeSheet();toast('Gasto apagado')};
SHEETS.spendView=({id})=>{const g=S.fin.spend.find(x=>x.id===id);if(!g)return {title:'Gasto',body:'<p class="empty">Este gasto já foi apagado.</p>',foot:''};
  return {title:esc(g.desc),body:`<div class="card"><div class="row"><div class="grow">${areaPill(g.area)}</div><div class="big num">${brl(g.value)}</div></div><small class="mut">${D.long(g.date)}${g.cat?' · '+esc(g.cat):''}${g.pay?' · '+esc(g.pay):''}</small></div>`,foot:`${delBtn('spendDel',id)}<button class="btn" data-a="closeSheet">Fechar</button>`}};
